/* HEXA BATTLEGROUNDS setup — PART 86 OF 94. Run parts in order. Safe to re-run. */ create function _spawn_pickups(p_arena uuid) returns int language plpgsql as $$ declare a arenas; v_n int; k text; v_want int; v_have int; v_try int; v_scale float8; l locations; b buildings; ang float8; rad float8; px float8; py float8; v_inside boolean; begin v_n := _spawn_pickups_v15(p_arena); select * into a from arenas where id = p_arena; v_scale := greatest(1.0, (select count(*) from teams where arena_id = p_arena and ready) / 15.0); foreach k in array array['medkit', 'shield', 'ammo_light', 'ammo_rifle', 'ammo_shell', 'gun_smg', 'gun_shotgun', 'gun_ar', 'gun_sniper', 'vest1', 'vest2', 'vest3', 'helmet1', 'helmet2', 'helmet3', 'jammer'] loop v_want := round(coalesce(_cfg(a.event_id, case when k in ('medkit', 'shield') then 'pickup_' || k else 'loot_' || k end), 0) * v_scale); select count(*) into v_have from pickups where arena_id = p_arena and taken_at is null and kind = k; v_inside := k in ('vest3', 'helmet3', 'gun_sniper', 'vest2', 'helmet2'); v_try := 0; while v_have < v_want and v_try < v_want * 3 loop v_try := v_try + 1; select * into l from locations loc where loc.enabled and loc.kind not in ('start', 'stairs') and (not v_inside or loc.level > 0 or loc.building is not null) and not (loc.building is not null and _sealed(p_arena, loc.building, loc.level)) order by random() limit 1; exit when l.id is null; ang := random() * 2 * pi(); rad := 0.006 + random() * 0.016; px := l.x + cos(ang) * rad; py := l.y + sin(ang) * rad; if l.level > 0 then select * into b from buildings where id = l.building; px := greatest(b.x0 + 0.006, least(b.x1 - 0.006, px)); py := greatest(b.y0 + 0.006, least(b.y1 - 0.006, py)); end if; insert into pickups(arena_id, kind, x, y, level, bldg) values (p_arena, k, greatest(0.02, least(0.98, px)), greatest(0.02, least(0.98, py)), l.level, case when l.level > 0 then l.building end); v_have := v_have + 1; v_n := v_n + 1; end loop; end loop; return v_n; end $$; create or replace function _team_extra(t teams) returns jsonb language sql stable as $$ select jsonb_build_object('vehicle', t.vehicle, 'kills', t.kills, 'buggy', case when t.buggy_x is not null and t.vehicle <> 'in' then jsonb_build_array(t.buggy_x, t.buggy_y) when t.dropped and t.vehicle = 'none' then to_jsonb(_buggy_bay(t.number, (_team_xy(t))[1], (_team_xy(t))[2])) end, 'in_plane', not t.dropped and t.jump_at is null and t.state <> 'traveling', 'parachute', not t.dropped and (t.jump_at is not null or t.state = 'traveling'), 'jump_at', t.jump_at, 'land_at', case when t.jump_at is not null then t.land_at when not t.dropped and t.state = 'traveling' then t.travel_arrive_at end, 'weapon', _weapon(t.id), 'fight_at', t.fight_at, 'armor', jsonb_build_object('vest', t.vest_lvl, 'helmet', t.helmet_lvl), 'weapon_sel', t.weapon_sel, 'jammed_until', case when t.jammed_until > now() then t.jammed_until end) $$; create or replace function _loadout_reset() returns trigger language plpgsql as $$ begin if new.phase in ('lobby', 'boarding') and old.phase is distinct from new.phase then update teams set vest_lvl = 0, helmet_lvl = 0, weapon_sel = null where arena_id = new.id; delete from inventory i using teams t where t.id = i.team_id and t.arena_id = new.id and i.item_id in ('ammo_light', 'ammo_rifle', 'ammo_shell', 'shotgun', 'ar'); end if; return new; end $$; drop trigger if exists arenas_loadout_reset on arenas; create trigger arenas_loadout_reset after update of phase on arenas for each row execute function _loadout_reset(); drop function if exists _captain_chat_v15(text, int, text); alter function captain_chat(text, int, text) rename to _captain_chat_v15; do $$ declare src text; out text; begin src := pg_get_functiondef('_captain_chat_v15(text, int, text)'::regprocedure); out := regexp_replace(src, 'from_team\s*=\s*t\.id\s+and\s+at\s*>', 'from_team = t.id and body not like ''📢 %'' and at >'); if out = src then raise exception 'chat patch did not apply'; end if; execute out; end $$; create function captain_chat(p_token text, p_to_team int, p_body text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_body text := trim(coalesce(p_body, '')); v_n int; begin if coalesce(p_to_team, -1) <> 0 then return _captain_chat_v15(p_token, p_to_team, p_body); end if; p := _auth_captain(p_token); select * into t from teams where id = p.team_id; if char_length(v_body) = 0 or char_length(v_body) > 270 then raise exception 'BAD_MESSAGE'; end if; if exists (select 1 from chat_messages where from_team = t.id and body like '📢 %' and at > now() - interval '45 seconds') then raise exception 'SLOW_DOWN'; end if; insert into chat_messages(arena_id, from_team, to_team, body) select t.arena_id, t.id, d.id, '📢 ' || v_body from teams d where d.arena_id = t.arena_id and d.ready and d.id <> t.id and not exists (select 1 from chat_blocks where team_id = d.id and blocked_team = t.id); get diagnostics v_n = row_count; perform _ping_arena(t.arena_id, 'chat'); return jsonb_build_object('sent', true, 'to', v_n); end $$; do $$ declare f record; src text; out text; v_n int := 0; begin for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' and pg_get_functiondef(p.oid) like '%(cm.from_team = t.id or (cm.to_team = t.id%' loop src := pg_get_functiondef(f.sig); out := replace(src, '(cm.from_team = t.id or (cm.to_team = t.id', '((cm.from_team = t.id and not (cm.body like ''📢 %'' and exists (select 1 from chat_messages c2 where c2.from_team = cm.from_team and c2.body = cm.body and c2.at = cm.at and c2.id < cm.id))) or (cm.to_team = t.id'); execute out; v_n := v_n + 1; end loop; if v_n = 0 then raise exception 'comms patch did not apply'; end if; end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary', 'host_online_start', 'host_online_auto', 'host_online_launch', 'online_event_info', 'online_join_segue', 'squad_equip']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-loadout-0', 'loadout', 'mission', 'Loadout Math', 'game', 2, array['testing','access','phase2','public','any']::text[], 'A rival squad is pinned behind a car. How many hits does it take to knock them out with the gun you choose?', '{"scout":{"title":"Through the scope","body":"Rival squad: 50 HP + 20 shield\nWearing: Vest level 1","big":true},"decoder":{"title":"Gun table (damage per hit)","body":"Pistol         3\nSMG            3\nShotgun        9\nAssault Rifle  4\nSniper         16\n\nVest 1 / 2 / 3 cuts every hit by 10 / 20 / 30 %, rounded to the nearest whole number (at least 1).","mono":true},"intel":{"title":"In your hands","body":"You are carrying: Pistol, SMG, Assault Rifle.\nThe captain says: use the Assault Rifle."}}'::jsonb, '[{"label":"Hits needed","accept":["18"]}]'::jsonb, false, 3, 200, 'Damage per hit after the vest, then divide HP + shield by it and round up.', 'Assault Rifle 4 → 4 per hit through vest 1; 70 ÷ 4 → 18', null, 25, 'published'), ('mission-loadout-1', 'loadout', 'mission', 'Loadout Math', 'game', 2, array['testing','access','phase2','public','any']::text[], 'A rival squad is pinned behind a car. How many hits does it take to knock them out with the gun you choose?', '{"scout":{"title":"Through the scope","body":"Rival squad: 90 HP + 10 shield\nWearing: Vest level 2","big":true},"decoder":{"title":"Gun table (damage per hit)","body":"Pistol         3\nSMG            3\nShotgun        9\nAssault Rifle  4\nSniper         16\n\nVest 1 / 2 / 3 cuts every hit by 10 / 20 / 30 %, rounded to the nearest whole number (at least 1).","mono":true},"intel":{"title":"In your hands","body":"You are carrying: SMG, Sniper, Shotgun.\nThe captain says: use the SMG."}}'::jsonb, '[{"label":"Hits needed","accept":["50"]}]'::jsonb, false, 3, 200, 'Damage per hit after the vest, then divide HP + shield by it and round up.', 'SMG 3 → 2 per hit through vest 2; 100 ÷ 2 → 50', null, 25, 'published'), ('mission-loadout-2', 'loadout', 'mission', 'Loadout Math', 'game', 2, array['testing','access','phase2','public','any']::text[], 'A rival squad is pinned behind a car. How many hits does it take to knock them out with the gun you choose?', '{"scout":{"title":"Through the scope","body":"Rival squad: 70 HP + 20 shield\nWearing: Vest level 3","big":true},"decoder":{"title":"Gun table (damage per hit)","bo